insert into public.academy_course_structures
    (app_slug, tier, structure, content_version)
insert into public.academy_quiz_questions
    (app_slug, tier, scope, module_key, ord, prompt, options, answer_index, explanation)
values
  ('wellcontrol', 'beginner', 'module', 'm01-what-a-kick-is', 1, 'What is the primary barrier in a drilling well?', '["The blowout preventer stack.", "The hydrostatic pressure of the mud column, which holds the formation fluids in the rock.", "The casing string and its cement sheath, which together isolate every exposed permeable zone from the wellbore.", "The mud column together with the choke manifold, acting as a single pressure containment system."]'::jsonb, 1, 'The BOP is the secondary barrier. It is used when the primary one has already failed.'),
  ('wellcontrol', 'beginner', 'module', 'm01-what-a-kick-is', 2, 'What is a kick?', '["A sudden loss of mud to the formation.", "Any unplanned rise in the standpipe pressure while drilling ahead at a constant flow rate and rotary speed.", "An increase in the equivalent circulating density caused by cuttings accumulating in the annulus above the bit.", "Formation fluid entering the wellbore because the pressure at the bottom fell below the pore pressure."]'::jsonb, 3, 'It is an influx, and it is caused by underbalance. Losses are the opposite failure.'),
  ('wellcontrol', 'beginner', 'module', 'm01-what-a-kick-is', 3, 'Which of these causes underbalance?', '["Swabbing on a trip out, which reduces the pressure at the bottom while the pipe is moving upward.", "Running the pipe in too quickly.", "Increasing the flow rate, because the extra annulus friction raises the equivalent circulating density.", "Adding barite to the active system, since the heavier mud takes longer to reach the bottom of the hole."]'::jsonb, 0, 'Running in fast causes surge, which raises the pressure and risks losses rather than a kick.'),
  ('wellcontrol', 'beginner', 'module', 'm01-what-a-kick-is', 4, 'What is the most reliable early warning sign of a kick while drilling?', '["A rise in the drill pipe pressure.", "A gradual fall in the rate of penetration as the bit dulls against a harder formation than the prognosis showed.", "An increase in the return flow rate out with the pump rate unchanged.", "A change in the shale shaker screen loading that indicates cavings are arriving alongside the drilled cuttings."]'::jsonb, 2, 'Flow out exceeding flow in means something is being added to the well, and only the formation can add it.'),
  ('wellcontrol', 'beginner', 'module', 'm01-what-a-kick-is', 5, 'Why is the pit gain a confirming sign rather than the first sign?', '["Pit level sensors are less accurate.", "The pits are large, so a small influx changes the level less than the flow line shows a rate change.", "Because the pits are open to atmosphere and their level is affected by evaporation, transfers and shaker losses at the same time.", "The pit gain is measured after the influx has already passed the shakers, so it lags the event by a full circulation."]'::jsonb, 1, 'Flow out is a rate, pit gain is its integral, and the rate moves first.'),
  ('wellcontrol', 'beginner', 'module', 'm01-what-a-kick-is', 6, 'Why shut in quickly?', '["To avoid damaging the shale shakers.", "Because the driller has a fixed time allowance before the well control event must be reported to the regulator.", "Because the mud pumps overheat if they run against a rising annulus pressure for more than a short period.", "Every extra second of underbalance admits more influx, and the influx volume drives everything that follows."]'::jsonb, 3, 'Kick tolerance, kill sheet difficulty and shoe risk all scale with the volume taken, and the volume grows with time.'),
  ('wellcontrol', 'beginner', 'module', 'm01-what-a-kick-is', 7, 'What does shutting in do to the well?', '["It stops the influx by letting the well pressure up until the bottom hole pressure matches the pore pressure.", "It seals the well and stops all pressure change.", "It transfers control from the mud column to the blowout preventer, which then holds the full formation pressure.", "It isolates the annulus from the drill string so that the two can be monitored on separate gauges."]'::jsonb, 0, 'The well pressures up until it balances. That is why there is a reading on both gauges afterwards.'),
  ('wellcontrol', 'beginner', 'module', 'm01-what-a-kick-is', 8, 'What are the two shut-in gauge readings called?', '["Initial and final circulating pressure.", "The standpipe pressure and the choke manifold pressure, read once the well has been closed and allowed to stabilise.", "Shut-in drill pipe pressure and shut-in casing pressure.", "The formation pressure and the maximum allowable annular surface pressure, both read directly from the rig gauges."]'::jsonb, 2, 'SIDPP and SICP. The first is clean, the second is contaminated by the influx.'),
  ('wellcontrol', 'beginner', 'module', 'm01-what-a-kick-is', 9, 'Why must the pressures be allowed to stabilise before reading?', '["Because the gauges have a slow response.", "The well takes time to pressure up to balance, and a reading taken too early is too low.", "Because the mud in the string is still moving downward under its own weight and adds a dynamic component to the reading.", "Because the choke has to be adjusted in stages, and each stage takes several minutes to reach a steady condition."]'::jsonb, 1, 'A pressure still rising is not the shut-in pressure. Reading it early understates the formation pressure.'),
  ('wellcontrol', 'beginner', 'module', 'm01-what-a-kick-is', 10, 'What is the hard kick warning sign while tripping?', '["A rise in the trip tank temperature.", "The pipe becoming progressively harder to pull as the trip proceeds, which indicates the influx is packing off around it.", "An increase in the number of stands that can be pulled before the trip tank needs topping up from the active system.", "The hole not taking the volume of mud that the removed steel should have displaced."]'::jsonb, 3, 'Trip tank volumes are the whole surveillance system while tripping, because there is no flow out to watch.'),
  ('wellcontrol', 'beginner', 'module', 'm01-what-a-kick-is', 11, 'What is the answer to a kick calculation ultimately for?', '["Deciding what mud weight to build and what pressure to hold on the choke while circulating it out.", "Reporting the event to the operator.", "Determining whether the well should be abandoned or whether a relief well needs to be planned and permitted.", "Establishing the pore pressure so that the geomechanics model can be recalibrated for the remainder of the section."]'::jsonb, 0, 'Two decisions, and every number in the course feeds one of them.'),
  ('wellcontrol', 'beginner', 'module', 'm01-what-a-kick-is', 12, 'What does this course assume about the blowout preventer?', '["It is a subsea stack on a floating rig.", "It is rated to a pressure well above anything the well can generate, so its rating never enters any calculation here.", "It is at surface, with no riser and no choke line.", "It contains an annular preventer and at least two sets of pipe rams, arranged in the standard configuration."]'::jsonb, 2, 'That assumption is stated in the Expert tier and it makes every number wrong offshore without a correction.'),
  ('wellcontrol', 'beginner', 'module', 'm01-what-a-kick-is', 13, 'Which is the correct order of the shut-in sequence, in principle?', '["Close the preventer, then stop the pump.", "Stop the pump, pick up to the correct space out, close the preventer, then read the gauges.", "Increase the pump rate to the kill rate first, then close the annular preventer while circulating and read the choke pressure.", "Read both gauges, then close the preventer once the readings have been recorded and the volumes confirmed."]'::jsonb, 1, 'Rig-specific variants exist. The principle is that the pump stops and the well is closed before anything is read.'),
  ('wellcontrol', 'beginner', 'module', 'm01-what-a-kick-is', 14, 'Why is the influx volume so important?', '["It sets the influx height, and the height is what determines the pressure deficit and the risk at the shoe.", "It determines how long the kill will take.", "Because it must be reported exactly, and an error in it invalidates the entire well control incident record.", "Because the pit gain has to be replaced from the reserve pits before circulation can begin at the kill rate."]'::jsonb, 0, 'Everything downstream is a function of the height, and the height is the volume divided by a capacity.'),
  ('wellcontrol', 'beginner', 'module', 'm01-what-a-kick-is', 15, 'What is the relationship between a kick and a blowout?', '["They are two words for the same event.", "A blowout involves gas and a kick involves liquid, which is why gas kicks are treated with far greater urgency.", "A kick occurs while drilling and a blowout occurs while tripping, because the string is not on bottom to circulate.", "A blowout is a kick that was not controlled, so every blowout began as a kick that could have been shut in."]'::jsonb, 3, 'That is why the detection and shut-in part of the subject carries the weight it does.'),
  ('wellcontrol', 'beginner', 'module', 'm02-volumes-and-strokes', 1, 'What is a span walk?', '["A survey of the wellbore trajectory.", "A method of estimating hole volume from the total depth and an average hole size, corrected for washout.", "Working down the string and up the annulus section by section, adding each piece of volume.", "A procedure for checking that the drill string tally matches the depth recorded by the driller at each connection."]'::jsonb, 2, 'Every volume in well control comes out of it, and it is arithmetic rather than a model.'),
  ('wellcontrol', 'beginner', 'module', 'm02-volumes-and-strokes', 2, 'Why is the string volume smaller than the annulus volume?', '["The string is a narrow bore inside the pipe, while the annulus is the gap between pipe and hole over the same depth.", "Because the string has thicker walls.", "Because the annulus includes the riser and the choke line, which together are larger than any string.", "Because the string volume excludes the drill collars, which are counted with the bottom hole assembly instead."]'::jsonb, 0, 'On both wells in this course the annulus is roughly three times the string.'),
  ('wellcontrol', 'beginner', 'module', 'm02-volumes-and-strokes', 3, 'What does pump output per stroke describe?', '["The pressure the pump can develop.", "The volume the pump delivers for one complete stroke, after allowing for volumetric efficiency.", "The theoretical displacement of the liners, which is fixed by their diameter and by the length of the stroke alone.", "The rate at which the pump moves mud, expressed as a volume divided by the time the stroke takes to complete."]'::jsonb, 1, 'It is a volume, not a rate. Multiplying by strokes per minute gives the rate.'),
  ('wellcontrol', 'beginner', 'module', 'm02-volumes-and-strokes', 4, 'What is volumetric efficiency?', '["The ratio of hydraulic power to input power.", "The proportion of the circulating system''s volume that passes the bit rather than being lost to the surface pits.", "A correction applied to the stroke count to allow for compressibility of the mud at high circulating pressures.", "The fraction of the pump''s theoretical displacement that actually leaves it, typically a little under one."]'::jsonb, 3, 'Valve leakage and fluid compressibility account for most of the shortfall, and it is measured rather than assumed.'),
  ('wellcontrol', 'beginner', 'module', 'm02-volumes-and-strokes', 5, 'Why are kill schedules written in strokes rather than in minutes?', '["Strokes measure volume, and volume is what displaces. Time only measures volume if the rate never changes.", "Because the pump has no time indication.", "Because the regulator requires kill sheets to be expressed in stroke counts for consistency between operators.", "Because the choke operator cannot read a clock and a pressure gauge at the same time during a kill operation."]'::jsonb, 0, 'A schedule in strokes survives a pump rate change. A schedule in time does not.'),
  ('wellcontrol', 'beginner', 'module', 'm02-volumes-and-strokes', 6, 'What are strokes to bit?', '["The strokes needed to circulate bottoms up.", "The strokes required to bring the pump to the kill rate from rest, measured during the slow circulating rate test.", "The strokes needed to displace the string volume, which moves fluid from surface down to the bit.", "The number of strokes between the moment the pump starts and the moment the choke pressure begins to respond."]'::jsonb, 2, 'It is the string volume divided by the pump output per stroke, and nothing else.'),
  ('wellcontrol', 'beginner', 'module', 'm02-volumes-and-strokes', 7, 'What is bottoms up?', '["The strokes to displace the whole hole once.", "The strokes needed to move fluid from the bit all the way up the annulus to surface.", "The time taken for a marked sample of mud to travel from the suction pit to the flow line and back into the pits.", "The point in the kill at which the kill mud reaches the bit and the drill pipe pressure stops falling."]'::jsonb, 1, 'It is the annulus volume divided by pump output per stroke. On both wells it is far larger than strokes to bit.'),
  ('wellcontrol', 'beginner', 'module', 'm02-volumes-and-strokes', 8, 'What is a full cycle?', '["Twice the annulus volume in strokes.", "The number of strokes required to circulate the influx from its point of entry to the choke manifold at surface.", "One complete round trip of the drill string, from the moment it leaves bottom to the moment it returns.", "Strokes to bit plus bottoms up, which is the whole circulating system displaced once."]'::jsonb, 3, 'It is the sum of the two, and the kill sheet''s schedule occupies only the first part of it.'),
  ('wellcontrol', 'beginner', 'module', 'm02-volumes-and-strokes', 9, 'Which depth do pressure calculations use?', '["True vertical depth, because hydrostatic pressure depends on height rather than on distance along the hole.", "Measured depth along the hole.", "The along-hole depth corrected for the average inclination of the section, which gives the effective column height.", "Whichever of the two is larger, since using the larger value keeps every pressure calculation on the safe side."]'::jsonb, 0, 'Volumes use measured depth. Pressures use true vertical depth. Mixing them is the classic error.'),
  ('wellcontrol', 'beginner', 'module', 'm02-volumes-and-strokes', 10, 'When you compute a capacity times a length to get a volume, which length goes in?', '["True vertical depth for the same reason as pressure.", "The vertical section, since that is the projection of the wellbore onto the plane containing the target and the surface location.", "Measured depth, because the fluid fills the hole along its length.", "Measured depth for the string and true vertical depth for the annulus, because the annulus is where pressures act."]'::jsonb, 2, 'A horizontal lateral holds mud along every metre of it, whatever its vertical rise, which is zero.'),
  ('wellcontrol', 'beginner', 'module', 'm02-volumes-and-strokes', 11, 'Why does the annulus capacity change with depth?', '["Because the mud compresses under pressure.", "The hole and the pipe both change size, so the gap between them is different at different depths.", "Because the annulus is washed out below the previous casing shoe and gauge above it, giving two distinct sections.", "Because cuttings settle in the lower part of the annulus and reduce the volume available to the circulating fluid."]'::jsonb, 1, 'A tight annulus around the collars, a wider one in the casing, and different capacities in each.'),
  ('wellcontrol', 'beginner', 'module', 'm02-volumes-and-strokes', 12, 'What does a smaller annulus capacity do to a given influx volume?', '["It makes the influx shorter and wider.", "It has no effect on the height, since the height is fixed by the pit gain and the influx density alone.", "It reduces the influx volume by compressing it, in proportion to the ratio of the two capacities involved.", "It makes the influx taller, because the same volume has less cross section to occupy."]'::jsonb, 3, 'Height is volume divided by capacity, and the height is what sets the pressure deficit.'),
  ('wellcontrol', 'beginner', 'module', 'm02-volumes-and-strokes', 13, 'Where in the well is the annulus capacity smallest?', '["Around the drill collars, where the pipe is thickest and the hole is at its narrowest open hole size.", "In the casing above the shoe.", "At the flow line, where the returns pass through the smallest cross section anywhere in the circulating system.", "In the horizontal lateral, because the pipe lies on the low side and blocks part of the available cross section."]'::jsonb, 0, 'Which is exactly where an influx enters, so it enters at its tallest.'),
  ('wellcontrol', 'beginner', 'module', 'm02-volumes-and-strokes', 14, 'What happens to an influx''s height as it rises past the shoe?', '["It stays the same, since volume is conserved.", "It increases in proportion to the pressure drop, which is the dominant effect for a gas influx moving up the annulus.", "It gets shorter for the same volume, because the casing annulus is wider than the open hole one.", "It becomes indeterminate, because the influx disperses into the mud and no longer has a definable top or bottom."]'::jsonb, 2, 'For gas that shortening competes with Boyle expansion, and expansion usually wins.'),
  ('wellcontrol', 'beginner', 'module', 'm02-volumes-and-strokes', 15, 'What is the practical reason to recount the volumes at every casing point?', '["Because the pump liners are usually changed too.", "The hole geometry changes, so every capacity and every stroke count in the standing part changes with it.", "Because the regulator requires a fresh kill sheet to be filed each time a casing string is landed and cemented.", "Because the mud weight is always raised at a casing point, and the volumes depend on the density of the fluid."]'::jsonb, 1, 'The standing part of a kill sheet is the part that goes stale, and this is one of the events that stales it.'),
  ('wellcontrol', 'beginner', 'module', 'm03-the-shut-in-pressures', 1, 'Why is the drill pipe described as a manometer?', '["Because it is a sealed tube of fluid.", "It holds a clean column of known mud, so its surface gauge reads the deficit at the bottom directly.", "Because the pressure inside it is transmitted through the bit nozzles without any loss when the pump is stopped.", "Because the drill pipe pressure gauge is calibrated against a mercury column before every well control drill."]'::jsonb, 1, 'Clean and known are both required. Lose either and the reading stops being a manometer reading.'),
  ('wellcontrol', 'beginner', 'module', 'm03-the-shut-in-pressures', 2, 'What does the shut-in drill pipe pressure represent?', '["The total formation pressure at the bit.", "The pressure that the blowout preventer is holding, measured on the string side rather than on the annulus side.", "The frictional pressure loss through the bit nozzles at the moment the pump was stopped and the well was closed.", "The amount by which the formation pressure exceeds the hydrostatic pressure of the mud in the string."]'::jsonb, 3, 'It is a deficit, and it is only meaningful together with the mud column it is a deficit against.'),
  ('wellcontrol', 'beginner', 'module', 'm03-the-shut-in-pressures', 3, 'How is formation pressure obtained from the shut-in drill pipe pressure?', '["Add the hydrostatic pressure of the mud in the string, computed at the true vertical depth of the bit.", "Multiply it by the mud gradient.", "Subtract the annulus friction from it and then add the mud column, using the measured depth rather than the vertical one.", "Divide it by the true vertical depth at the bit and then multiply the result by gravity and the mud density."]'::jsonb, 0, 'One addition. The whole calculation is a sum of two pressures.'),
  ('wellcontrol', 'beginner', 'module', 'm03-the-shut-in-pressures', 4, 'Why does the casing gauge normally read higher than the drill pipe gauge?', '["Because the annulus is larger in cross section.", "Because the choke restricts the flow out of the annulus and the restriction shows up as an elevated surface reading.", "The annulus contains the influx, which is lighter than mud, so its column provides less pressure.", "Because the casing gauge measures at the wellhead while the drill pipe gauge measures at the standpipe, higher up."]'::jsonb, 2, 'The deficit is bigger on the side that has the light fluid in it.'),
  ('wellcontrol', 'beginner', 'module', 'm03-the-shut-in-pressures', 5, 'What does the difference between the two shut-in readings tell you?', '["The size of the influx in cubic metres.", "How much pressure the influx failed to provide, which leads to its height and its density.", "The frictional pressure loss around the circulating system at the slow rate used for the kill operation.", "The margin remaining before the casing shoe reaches its fracture pressure and the well begins to lose returns."]'::jsonb, 1, 'It is a pressure difference, and module 2 of the Professional tier turns it into an influx description.'),
  ('wellcontrol', 'beginner', 'module', 'm03-the-shut-in-pressures', 6, 'When does the drill pipe stop being a reliable manometer?', '["When there is a float in the string, when the bit is plugged, or when the string is off bottom or out of the hole.", "Only when the pump is still running.", "When the mud weight in the string differs from the mud weight in the annulus by more than a small tolerance.", "When the shut-in casing pressure exceeds the maximum allowable annular surface pressure for that hole section."]'::jsonb, 0, 'Four cases, and three of them are common. Each has its own workaround.'),
  ('wellcontrol', 'beginner', 'module', 'm03-the-shut-in-pressures', 7, 'What does a float valve in the string do to the shut-in reading?', '["It has no effect on a static reading.", "It amplifies the reading in proportion to the ratio of the string bore to the nozzle area at the bit.", "It causes the reading to oscillate, because the valve opens and closes as the pressure fluctuates below it.", "It blocks the pressure from reaching the surface gauge, so the drill pipe reads low or reads nothing."]'::jsonb, 3, 'The standard workaround is to pump slowly until the float opens and read the pressure at which it does.'),
  ('wellcontrol', 'beginner', 'module', 'm03-the-shut-in-pressures', 8, 'If the bit nozzles are plugged, what happens to the shut-in drill pipe pressure?', '["It rises above the casing pressure.", "It reads the formation pressure directly, without any need to add the hydrostatic column of the mud inside the string.", "It stops responding to the formation, because the string is no longer connected to the annulus.", "It becomes equal to the casing pressure, because both gauges then measure the same isolated closed volume."]'::jsonb, 2, 'The manometer needs a hydraulic path to the bottom. A plugged bit removes it.'),
  ('wellcontrol', 'beginner', 'module', 'm03-the-shut-in-pressures', 9, 'Why is the casing pressure hard to invert into a formation pressure?', '["Because the casing gauge is less accurate.", "Its column contains mud and influx in unknown proportions at unknown positions in the annulus.", "Because the annulus is open to the choke manifold, and the manifold pressure is not the same as the annulus pressure.", "Because the casing pressure includes the frictional loss up the annulus even when the pumps have been stopped."]'::jsonb, 1, 'Inverting it needs an assumption, and that assumption is what the Professional tier''s module 2 supplies.'),
  ('wellcontrol', 'beginner', 'module', 'm03-the-shut-in-pressures', 10, 'What is the correct reading order after shutting in?', '["Let both gauges stabilise, read the drill pipe first, then the casing, then record the pit gain.", "Read the casing gauge first, since it responds fastest.", "Read the pit gain first, because the influx volume determines whether the other two readings can be trusted at all.", "Read both gauges at the same moment, so that the difference between them is not distorted by any migration of the influx."]'::jsonb, 0, 'The order matters less than the stabilisation. Reading before the well has balanced understates everything.'),
  ('wellcontrol', 'beginner', 'module', 'm03-the-shut-in-pressures', 11, 'What does a rising shut-in casing pressure with a steady drill pipe pressure suggest?', '["The choke is leaking.", "The formation is continuing to flow into the wellbore, which means the well has not yet reached a balanced condition.", "The mud in the annulus is settling, so the effective density of the column above the influx is slowly increasing.", "Gas is migrating up the annulus, carrying its pressure with it."]'::jsonb, 3, 'Migration raises both gauges eventually. It shows on the annulus side first because that is where the gas is.'),
  ('wellcontrol', 'beginner', 'module', 'm03-the-shut-in-pressures', 12, 'Why must both readings be recorded rather than just the drill pipe one?', '["Because the regulator requires both to be logged.", "Because the casing pressure is the one used to build the kill sheet''s pressure schedule between the two circulating pressures.", "Their difference is the only information available about what the influx actually is.", "Because the drill pipe reading alone cannot be converted into a formation pressure without the annulus reading as a check."]'::jsonb, 2, 'Height, density and classification all come out of the difference and the pit gain.'),
  ('wellcontrol', 'beginner', 'module', 'm03-the-shut-in-pressures', 13, 'What is the third measurement taken at shut-in?', '["The slow circulating rate pressure.", "The pit gain, which is the volume of influx that entered before the well was closed.", "The maximum allowable annular surface pressure, computed from the leak-off test result and the current mud weight.", "The temperature of the returns at the flow line, which indicates whether the influx is gas or a formation liquid."]'::jsonb, 1, 'Three numbers at shut-in, and every calculation that follows uses at least one of them.'),
  ('wellcontrol', 'beginner', 'module', 'm03-the-shut-in-pressures', 14, 'Why does the same shut-in drill pipe pressure mean different formation pressures on different wells?', '["Because the mud column that the deficit sits on top of depends on the true vertical depth at the bit.", "Because the mud weights are always different.", "Because the pore pressure gradient varies between fields, and the shut-in reading is calibrated against that gradient.", "Because a deeper well has more annulus friction, which adds to the reading even after the pump has been stopped."]'::jsonb, 0, 'A deep bit gives a large column and a large formation pressure for the same surface deficit.'),
  ('wellcontrol', 'beginner', 'module', 'm03-the-shut-in-pressures', 15, 'What is the equivalent mud weight form of the formation pressure?', '["The formation pressure multiplied by the mud gradient.", "The ratio of the shut-in drill pipe pressure to the shut-in casing pressure, scaled by the current mud density in use.", "The formation pressure divided by gravity and by the true vertical depth, expressed as a density.", "The pressure at the shoe expressed as the mud weight that would fracture it, which is the fracture equivalent weight."]'::jsonb, 2, 'It equals the kill mud weight exactly, and that equality is the whole basis of the kill mud calculation.'),
  ('wellcontrol', 'beginner', 'module', 'm04-the-kill-mud', 1, 'What is kill mud?', '["Mud with a lost circulation material additive.", "Mud weighted to the fracture gradient of the shoe, so that the well is protected against any further influx at all.", "Mud heavy enough that its hydrostatic column alone balances the formation pressure at the bit.", "The mud already in the hole, circulated at the slow rate until the influx has been displaced from the annulus."]'::jsonb, 2, 'It restores the primary barrier. Once it is round, the well holds itself without help from the choke.'),
  ('wellcontrol', 'beginner', 'module', 'm04-the-kill-mud', 2, 'How is the kill mud density computed?', '["Add the shut-in drill pipe pressure divided by gravity and true vertical depth to the current mud density.", "Multiply the current density by the pressure ratio.", "Divide the formation pressure by the fracture pressure and multiply the result by the density currently in the hole.", "Take the difference between the two shut-in readings and convert it to a density at the true vertical depth of the shoe."]'::jsonb, 0, 'The added term is the deficit expressed as a density. It is one division and one addition.'),
  ('wellcontrol', 'beginner', 'module', 'm04-the-kill-mud', 3, 'Why does a shallow bit need a bigger weight increase for the same shut-in reading?', '["Because shallow formations are always weaker.", "Each kilogram per cubic metre of mud buys less pressure when the column it acts over is shorter.", "Because the annulus capacity is larger in a shallow well, so more volume of heavy mud is needed to displace it.", "Because the shut-in pressure has less time to stabilise on a shallow well, so the reading is systematically high."]'::jsonb, 1, 'Pressure is density times gravity times height. Halve the height and you need twice the density change.'),
  ('wellcontrol', 'beginner', 'module', 'm04-the-kill-mud', 4, 'What is a trip margin?', '["A safety factor applied to the kill mud.", "The volume of mud held in the trip tank to replace the steel removed from the hole as the string is pulled.", "The difference between the pore pressure and the fracture pressure, expressed as an equivalent mud weight range.", "Extra mud weight carried above the balance point, so the well stays overbalanced while swabbing on a trip."]'::jsonb, 3, 'It buys overbalance against swab, and it costs kick tolerance at the shoe. Both at once.'),
  ('wellcontrol', 'beginner', 'module', 'm04-the-kill-mud', 5, 'Carrying extra weight above the balance point costs the well something. What?', '["Kick tolerance, because a heavier mud leaves less headroom between the mud column and the fracture pressure.", "Rate of penetration only.", "Nothing measurable, since the extra weight is small compared with the total column and does not affect the shoe.", "The ability to read the shut-in drill pipe pressure accurately, because the string column is no longer clean."]'::jsonb, 0, 'That trade is the reason trip margins are debated rather than simply always applied.'),
  ('wellcontrol', 'beginner', 'module', 'm04-the-kill-mud', 6, 'Why is there a delay between deciding to kill and having kill mud?', '["The kill sheet takes a long time to complete.", "The kill mud must be circulated through the shakers several times before it is homogeneous enough to be pumped downhole.", "The mud has to be weighted up in the pits, and that takes time and barite.", "The blowout preventer cannot be closed until the mud engineer has certified the density of the new mud in the pits."]'::jsonb, 2, 'That delay is the whole reason one of the two kill methods exists.'),
  ('wellcontrol', 'beginner', 'module', 'm04-the-kill-mud', 7, 'What happens in the well while the kill mud is being mixed?', '["Nothing changes, because the well is closed.", "The well sits shut in, and gas in the annulus migrates upward, raising both surface gauges.", "The influx dissolves gradually into the mud, which reduces the shut-in casing pressure to the drill pipe value.", "The formation continues to flow into the wellbore until the mud weight has been raised to the kill value."]'::jsonb, 1, 'That migration is why waiting is not free, and it is the reason the Driller''s Method exists.'),
  ('wellcontrol', 'beginner', 'module', 'm04-the-kill-mud', 8, 'What do you do if you cannot build kill mud to the required weight?', '["Circulate with whatever mud is available.", "Increase the pump rate so that the extra annulus friction makes up the shortfall in hydrostatic pressure at the bit.", "Bullhead the influx back into the formation using the mud already in the hole, then resume drilling ahead normally.", "Hold the well shut in and manage the pressures while a solution is arranged, rather than circulating with light mud."]'::jsonb, 3, 'Circulating out with insufficient weight leaves the well underbalanced when the pumps stop, which is where it started.'),
  ('wellcontrol', 'beginner', 'module', 'm04-the-kill-mud', 9, 'Why does the kill mud weight equal the pore pressure gradient expressed as a density?', '["Because balancing means the mud column equals the formation pressure, and that is the definition of the gradient.", "Because both are measured in the same units.", "Because the pore pressure gradient is always quoted at the shoe, and the kill mud is designed to balance the shoe.", "Because the shut-in drill pipe pressure is defined as the difference between the two gradients at the bit depth."]'::jsonb, 0, 'It is not a coincidence. It is the same statement written two ways.'),
  ('wellcontrol', 'beginner', 'module', 'm04-the-kill-mud', 10, 'What is overkill?', '["Circulating more than one full cycle.", "Applying a pressure on the choke that exceeds the value the kill sheet''s schedule calls for at that stroke count.", "Building mud heavier than the balance point requires, beyond any deliberate trip margin.", "Using the Wait and Weight method when the Driller''s Method would have been sufficient for the size of influx taken."]'::jsonb, 2, 'It wastes barite, it costs kick tolerance, and on a narrow margin well it can fracture the shoe.'),
  ('wellcontrol', 'beginner', 'module', 'm04-the-kill-mud', 11, 'Which shut-in reading goes into the kill mud calculation?', '["The casing pressure, since it is the larger value.", "The drill pipe pressure, because the string column is clean and its reading is a true deficit.", "Both of them, averaged, so that the calculation is not distorted by an error in either individual gauge reading.", "Whichever of the two stabilised first, because the other one is still being affected by migration of the influx."]'::jsonb, 1, 'The casing reading has the influx in its column and cannot be inverted without an assumption about it.'),
  ('wellcontrol', 'beginner', 'module', 'm04-the-kill-mud', 12, 'What does the kill mud do to the pressure at the casing shoe?', '["It lowers it by removing the influx.", "It leaves it unchanged, because the shoe pressure is fixed by the fracture gradient rather than by the mud in the hole.", "It raises it only below the shoe, since the mud above the shoe is inside casing and does not load the formation.", "It raises it, because a heavier column exerts more pressure at every depth including the shoe."]'::jsonb, 3, 'Which is exactly why kill mud weight and kick tolerance pull against each other.'),
  ('wellcontrol', 'beginner', 'module', 'm04-the-kill-mud', 13, 'What is the relationship between kill mud weight and kick tolerance?', '["They pull in opposite directions: more kill mud weight means less headroom at the shoe and less tolerance.", "They rise and fall together.", "They are independent, because kick tolerance is a property of the geometry and kill mud is a property of the fluid.", "Kick tolerance sets an upper limit on the kill mud weight, above which the kill sheet cannot be completed at all."]'::jsonb, 0, 'The Expert tier makes that trade the basis of the casing point calculation.'),
  ('wellcontrol', 'beginner', 'module', 'm04-the-kill-mud', 14, 'If the kill mud weight comes out below the mud already in the hole, what does that mean?', '["The influx was liquid rather than gas.", "The formation pressure has fallen since the kick was taken, which happens when a depleted zone is drilled into.", "The well was already overbalanced, so the reading or the pit gain needs rechecking.", "The shut-in drill pipe pressure was recorded before the well had finished stabilising and is therefore too high."]'::jsonb, 2, 'A negative deficit is arithmetically possible and physically means the input data is wrong.'),
  ('wellcontrol', 'beginner', 'module', 'm04-the-kill-mud', 15, 'What restores the primary barrier?', '["Closing the blowout preventer.", "Kill mud all the way round, so the hydrostatic column alone holds the formation back.", "Circulating the influx out of the annulus, after which the original mud is sufficient to hold the well in balance.", "Holding the correct pressure on the choke, which keeps the bottom hole pressure at the formation value throughout."]'::jsonb, 1, 'The BOP is the secondary barrier and holding choke pressure is a temporary substitute. Only kill mud restores the first.'),
  ('wellcontrol', 'beginner', 'module', 'm05-circulating-it-out', 1, 'What are the two standard kill methods?', '["Bullheading and the volumetric method.", "The Driller''s Method and the Wait and Weight Method, distinguished by when the kill mud is pumped.", "Constant bottom hole pressure and constant surface pressure, chosen according to the strength of the casing shoe.", "The concurrent method and the reverse circulation method, applied depending on whether the string is on bottom."]'::jsonb, 1, 'Both hold the bottom hole pressure constant. They differ only in the order of two operations.'),
  ('wellcontrol', 'beginner', 'module', 'm05-circulating-it-out', 2, 'What does the Driller''s Method do first?', '["Waits for the kill mud to be mixed.", "Raises the mud weight in the pits while the influx is held still.", "Pumps heavy mud down to push the influx back into the formation.", "Circulates the influx out of the annulus using the mud already in the hole, before any kill mud is built at all."]'::jsonb, 3, 'Two circulations: the first removes the influx, the second replaces the mud.'),
  ('wellcontrol', 'beginner', 'module', 'm05-circulating-it-out', 3, 'Why does the Driller''s Method start sooner?', '["It needs no kill mud to begin, so the influx is removed while the barite is still being added to the pits.", "Because it uses fewer strokes overall.", "Because the pump can be brought up to the kill rate faster when the mud density has not been changed at all.", "Because it does not require a kill sheet to be completed before circulation begins, only a slow rate pressure."]'::jsonb, 0, 'Getting the influx out early is the argument for it, and it is a strong one when gas is migrating.'),
  ('wellcontrol', 'beginner', 'module', 'm05-circulating-it-out', 4, 'What does the Wait and Weight Method do?', '["Circulates twice with the original mud.", "Holds the well shut in until the influx has migrated to surface, then bleeds it off through the choke in stages.", "Builds the kill mud first, then circulates the influx out and the kill mud round in one pass.", "Pumps kill mud down the annulus while the original mud is displaced up the string and out through the standpipe."]'::jsonb, 2, 'One circulation. Whether it takes less total time depends on how long the weighting up takes.'),
  ('wellcontrol', 'beginner', 'module', 'm05-circulating-it-out', 5, 'Which method gives lower pressure at the casing shoe?', '["The Driller''s Method, by a wide margin, on every well.", "Wait and Weight.", "Neither, since both hold the bottom hole pressure constant and therefore hold the shoe pressure constant as well.", "Whichever one is completed faster, because the shoe pressure depends mainly on how long the influx sits against it."]'::jsonb, 1, 'Heavier mud below the shoe earlier means less surface pressure needed, and the shoe sees the difference.'),
  ('wellcontrol', 'beginner', 'module', 'm05-circulating-it-out', 6, 'What is the argument for the Driller''s Method despite the higher shoe pressure?', '["It starts immediately, and getting a migrating gas influx out of the well early is worth a great deal.", "It uses less barite in total.", "It gives a lower maximum casing pressure at surface, which matters more than the shoe pressure on most wells.", "It requires only one circulation, so the total pumping time and the wear on the choke are both reduced."]'::jsonb, 0, 'It is a trade between shoe risk and delay risk, and the right answer depends on the well.'),
  ('wellcontrol', 'beginner', 'module', 'm05-circulating-it-out', 7, 'What holds the bottom hole pressure constant in both methods?', '["The pump, held at a constant rate.", "The kill mud, which balances the formation once it is round.", "The blowout preventer, which fixes the annular pressure.", "The choke, adjusted continuously so that the drill pipe pressure follows the schedule that the kill sheet sets out."]'::jsonb, 3, 'The pump rate is held steady so the friction term is steady. The choke does the controlling.'),
  ('wellcontrol', 'beginner', 'module', 'm05-circulating-it-out', 8, 'What is the slow circulating rate pressure?', '["The pressure at which the pump stalls.", "The pressure the choke must hold once the kill mud has reached the bit, which is the final circulating pressure.", "The measured system pressure loss at a low pump rate, taken before it is needed.", "The rate at which the annulus pressure falls when the pump is slowed from drilling rate down to the kill rate."]'::jsonb, 2, 'It is measured rather than computed, which is why the kill sheet needs no hydraulics model at all.'),
  ('wellcontrol', 'beginner', 'module', 'm05-circulating-it-out', 9, 'Why is a kill circulated slowly?', '["To reduce wear on the pump liners.", "Lower rate means less annulus friction at the shoe and gives the choke operator time to respond.", "Because the influx expands more slowly at a low rate, which keeps the pit gain within the capacity of the trip tank.", "Because the kill mud needs time to displace the original mud without the two fluids mixing at the interface."]'::jsonb, 1, 'Two reasons, and the shoe one is usually the harder constraint.'),
  ('wellcontrol', 'beginner', 'module', 'm05-circulating-it-out', 10, 'At what interval should that measurement be repeated?', '["Routinely, typically at every shift and after any change to the mud, the bit or the string configuration.", "Once at the start of the well.", "Only when a kick has been taken, since it is the first measurement required after the well has been shut in.", "At every connection, because the pressure changes as each new stand adds to the length of the circulating system."]'::jsonb, 0, 'It belongs to the standing part of the kill sheet, and the standing part goes stale.'),
  ('wellcontrol', 'beginner', 'module', 'm05-circulating-it-out', 11, 'Why are two slow rates usually recorded rather than one?', '["Because one of the two is a check on the other one.", "Because the pressure loss is not linear in rate, and two points allow the relationship to be interpolated properly.", "Because one rate is used for the string side of the sheet and the other is used for the annulus side of it.", "So either rate can be used without a fresh measurement."]'::jsonb, 3, 'Flexibility during the event, when there is no opportunity to stop and measure.'),
  ('wellcontrol', 'beginner', 'module', 'm05-circulating-it-out', 12, 'What does holding the bottom hole pressure constant achieve?', '["It keeps the choke pressure at zero.", "It ensures that the influx expands at a uniform rate all the way up the annulus, which simplifies the calculation.", "It stops any further influx without exceeding the pressure the formations can stand.", "It removes the need to build kill mud, since the pressure is maintained by the choke throughout the operation."]'::jsonb, 2, 'Slightly above the pore pressure and below the fracture pressure everywhere. That is the whole objective.'),
  ('wellcontrol', 'beginner', 'module', 'm05-circulating-it-out', 13, 'Which method needs a completed kill sheet before pumping starts?', '["Both of the two methods need one equally.", "Wait and Weight.", "The Driller''s Method, since its first circulation must be run at exactly the pressure recorded at shut-in.", "Neither, because both are run by holding the casing pressure steady and reading the drill pipe as a check."]'::jsonb, 1, 'The Driller''s first circulation holds a constant drill pipe pressure and needs much less arithmetic.'),
  ('wellcontrol', 'beginner', 'module', 'm05-circulating-it-out', 14, 'What happens to the drill pipe pressure during the Driller''s Method first circulation?', '["It is held constant, because the mud density in the string is not changing while the influx is displaced.", "It falls steadily to the final value.", "It rises as the influx approaches surface and expands, then falls sharply once the influx has been bled off.", "It follows the same schedule as in the Wait and Weight method, since both hold the bottom hole pressure constant."]'::jsonb, 0, 'Constant density in the string means constant hydrostatic, so constant surface pressure holds the bottom steady.'),
  ('wellcontrol', 'beginner', 'module', 'm05-circulating-it-out', 15, 'Which method is chosen more often in practice, and why?', '["Wait and Weight, universally.", "The Driller''s Method, because it is simpler to run and requires no arithmetic to be done during the event itself.", "It varies by operator and by well, because the trade between shoe risk and delay is genuinely balanced.", "Whichever one the kill sheet in use was designed for, since the two sheets have incompatible schedule formats."]'::jsonb, 2, 'Anyone who tells you one is always right has not stated the well conditions they are assuming.'),
  ('wellcontrol', 'beginner', 'module', 'm06-the-associate-reading', 1, 'What is the one sentence this tier reduces to?', '["Always shut the well in immediately.", "Build kill mud to the calculated weight and circulate it round at the slow rate that was measured last shift.", "Keep the pressure at the bottom of the hole above the pore pressure, and know what it is doing when you cannot.", "Read both gauges, record the pit gain, and hand the numbers to the person completing the kill sheet."]'::jsonb, 2, 'Everything in the five modules is either a way of keeping it there or a way of finding out where it is.'),
  ('wellcontrol', 'beginner', 'module', 'm06-the-associate-reading', 2, 'Which well does the Associate capstone grade?', '["The slant well, while the lessons taught the same quantities on the horizontal one.", "The horizontal well used throughout the lessons.", "Both wells, with three fields taken from each so that the learner has to walk two separate surveys and two strings.", "Whichever well the learner selects in the volume explorer panel before starting the capstone attempt."]'::jsonb, 0, 'Same method, different well. That is the point of the arrangement.'),
  ('wellcontrol', 'beginner', 'module', 'm06-the-associate-reading', 3, 'Which two of the six graded fields are pressures rather than volumes or depths?', '["The two shut-in gauge readings.", "The initial and final circulating pressures, which are the outputs of the kill sheet the tier has been building.", "The formation pressure and the kill mud density, both computed from the shut-in drill pipe pressure at the bit.", "None of them. The Associate capstone grades volumes, stroke counts and depths only."]'::jsonb, 3, 'Pressures are the Professional tier''s business. This one certifies the span walk and the two depths.'),
  ('wellcontrol', 'beginner', 'module', 'm06-the-associate-reading', 4, 'Why does the capstone ask for the two true vertical depths?', '["Because they are the easiest fields to grade.", "Because every pressure calculation in the next tier needs them, and they come out of the same survey walk.", "Because the true vertical depth is the only quantity in the course that cannot be checked against the goldens.", "Because the volumes cannot be computed without knowing the vertical rise of each section of the wellbore first."]'::jsonb, 1, 'Volumes need measured depth. The depths are the bridge into the pressure work.'),
  ('wellcontrol', 'beginner', 'module', 'm06-the-associate-reading', 5, 'What order should the six fields be worked in?', '["The volumes first, then the strokes that follow from them, then the two depths from the same survey walk.", "The depths first, then everything else.", "In the order they appear on the capstone form, since each field''s answer is used as an input to the one after it.", "The strokes first, because they are the only fields with a loose tolerance and can be checked against the panel."]'::jsonb, 0, 'Strokes are volumes divided by pump output, so the volumes have to exist before the strokes can.'),
  ('wellcontrol', 'beginner', 'module', 'm06-the-associate-reading', 6, 'What is the commonest arithmetic error in the span walk?', '["Forgetting the pump volumetric efficiency.", "Adding the string volume to the annulus volume and reporting the total where only one of the two was asked for.", "Using true vertical depth where measured depth belongs, which shortens every section.", "Reading the annulus capacity at the shoe rather than at the bit, which understates the height of the influx."]'::jsonb, 2, 'On a horizontal well it is catastrophic. On a slant well it is merely wrong.'),
  ('wellcontrol', 'beginner', 'module', 'm06-the-associate-reading', 7, 'Why are the capstone tolerances tight on the volumes and loose on the strokes?', '["Because strokes are larger numbers.", "Strokes carry a pump efficiency that is a measured quantity, so a small spread there is legitimate.", "Because the volume fields are graded against the published goldens while the stroke fields are graded against the panel.", "Because the pump output per stroke is not given in the capstone and each learner has to estimate it independently."]'::jsonb, 1, 'Volumes are pure geometry and should agree exactly. Strokes inherit an efficiency.'),
  ('wellcontrol', 'beginner', 'module', 'm06-the-associate-reading', 8, 'What does the Associate tier hand to the Professional tier?', '["The kill mud density and the formation pressure.", "The maximum allowable annular surface pressure, which the Professional tier compares against the casing readings.", "The classification of the influx as gas, liquid or mixed, together with the height it occupies in the annulus.", "The volumes, the stroke counts and the two depths, which are the standing part of a kill sheet."]'::jsonb, 3, 'Six of the kill sheet''s inputs are already in hand by the end of this tier.'),
  ('wellcontrol', 'beginner', 'module', 'm06-the-associate-reading', 9, 'Which three numbers does a kick event supply that a span walk cannot?', '["The two shut-in gauge readings and the pit gain, all measured at the time of the event itself.", "The mud weight, the pump rate and the bit depth.", "The slow circulating rate pressure, the pump efficiency and the annulus capacity opposite the drill collars.", "The fracture gradient at the shoe, the pore pressure in the reservoir and the temperature at the bottom of the hole."]'::jsonb, 0, 'That is why a kill sheet cannot be completed in advance, only prepared.'),
  ('wellcontrol', 'beginner', 'module', 'm06-the-associate-reading', 10, 'What does the tier say about reading the casing gauge?', '["It is the more reliable of the two gauges.", "It should be read before the drill pipe gauge, because it responds first and stabilises sooner after shut-in.", "It cannot be inverted into a formation pressure without an assumption about the influx.", "It gives the formation pressure directly once the hydrostatic pressure of the annulus mud has been added to it."]'::jsonb, 2, 'The assumption is supplied in the next tier, and it is the single bubble.'),
  ('wellcontrol', 'beginner', 'module', 'm06-the-associate-reading', 11, 'Which habit does the tier name as the most useful at the well site?', '["Memorising the kill mud formula.", "Keeping the standing part of the kill sheet current, because it goes stale every stand.", "Recording the slow circulating rate pressure at both rates every time the pump liners are changed on the rig floor.", "Comparing the pit gain against the kick tolerance before deciding which of the two kill methods is appropriate."]'::jsonb, 1, 'A sheet with yesterday''s volumes on it is worse than no sheet, because it looks complete.'),
  ('wellcontrol', 'beginner', 'module', 'm06-the-associate-reading', 12, 'What is the relationship between the pit gain and everything that follows it?', '["It has no bearing on the calculations.", "It determines how many strokes will be needed to circulate the influx out of the annulus at the chosen kill rate.", "It sets the kill mud weight, because a larger influx means a larger underbalance and therefore a heavier mud.", "It fixes the influx height once the annulus capacity is known, and the height drives every later number."]'::jsonb, 3, 'Height is volume over capacity, and height is what turns into a pressure deficit.'),
  ('wellcontrol', 'beginner', 'module', 'm06-the-associate-reading', 13, 'Where do all six graded numbers place the well control equipment?', '["That it sits at surface, so every gauge reading is taken with nothing between it and the annulus.", "That it is rated above the formation pressure.", "That it is a subsea stack, so the choke line friction must be measured and subtracted from every casing reading.", "That it is closed for the whole of the operation, including while the kill mud is being circulated round the well."]'::jsonb, 0, 'The Expert tier states the assumption formally and gives the offshore correction.'),
  ('wellcontrol', 'beginner', 'module', 'm06-the-associate-reading', 14, 'Why does the tier teach the two kill methods before any kill sheet arithmetic?', '["Because the methods are simpler to remember.", "Because the choice of method determines which of the six inputs to the kill sheet have to be measured at the well site.", "Because the arithmetic only makes sense once you know which operation it is describing.", "Because the Driller''s Method requires no arithmetic at all and is therefore the appropriate starting point."]'::jsonb, 2, 'A schedule from initial to final circulating pressure is meaningless without the picture of kill mud going down the string.'),
  ('wellcontrol', 'beginner', 'module', 'm06-the-associate-reading', 15, 'What should you carry forward about the primary and secondary barriers?', '["They are interchangeable in an emergency.", "The mud column is the primary barrier and the preventer is the secondary one, used after the first has failed.", "The preventer is the primary barrier while drilling and the mud column takes over once the well has been shut in.", "The casing and its cement form the primary barrier, with the mud column acting as a secondary containment layer."]'::jsonb, 1, 'Restoring the primary barrier is what the whole kill operation is for.'),
  ('wellcontrol', 'beginner', 'final', null, 1, 'Which barrier does the mud column provide?', '["The primary one, holding formation fluid in the rock by hydrostatic pressure alone.", "The secondary barrier.", "Neither, since barriers are mechanical and the mud column is a fluid that can be displaced or lost at any time.", "Both, because the mud column also supplies the pressure that closes the annular preventer against the pipe."]'::jsonb, 0, 'The preventer is the secondary barrier, used once the primary one has already failed.'),
  ('wellcontrol', 'beginner', 'final', null, 2, 'Underbalance means what?', '["The mud weight is below the fracture gradient.", "The pressure at the bottom of the hole has fallen below the pore pressure of an exposed formation.", "The equivalent circulating density has dropped below the static mud weight because the pumps have been stopped.", "The pressure at the casing shoe has fallen below the pressure at the bit, which drives flow up the annulus."]'::jsonb, 1, 'It is the condition that admits an influx, and every kick cause is a way of producing it.'),
  ('wellcontrol', 'beginner', 'final', null, 3, 'Swabbing occurs when the pipe is doing what?', '["Rotating at high speed on bottom.", "Being run into the hole quickly, so the fluid ahead of it is displaced and the pressure at the bottom rises sharply.", "Moving upward, which reduces the pressure below the bottom hole assembly.", "Held stationary while the mud gels, which lowers the effective density of the column above the bit."]'::jsonb, 2, 'Running in causes surge and raises the pressure. Pulling out causes swab and lowers it.'),
  ('wellcontrol', 'beginner', 'final', null, 4, 'Which sign of a kick appears first?', '["A gain in the active pit volume.", "A drop in the standpipe pressure accompanied by an increase in the rate of penetration through the interval.", "Gas readings at the flow line, which rise as the influx reaches surface and is separated from the returns.", "An increase in flow out with the pump rate unchanged."]'::jsonb, 3, 'Flow out is a rate, pit gain is its integral, and the rate moves first.'),
  ('wellcontrol', 'beginner', 'final', null, 5, 'What is the surveillance system while tripping?', '["The trip tank, compared against the volume the removed or added steel should displace.", "The flow line paddle.", "The standpipe pressure gauge, watched for the small rise that indicates the annulus is beginning to load with influx.", "The mud logging unit''s gas chromatograph, which detects the influx before it becomes large enough to change any volume."]'::jsonb, 0, 'There is no flow out to watch when the pumps are off, so volumes are the whole of it.'),
  ('wellcontrol', 'beginner', 'final', null, 6, 'A driller sees flow out rise and closes the well within seconds. What did that speed buy?', '["To satisfy the reporting requirement.", "The influx volume grows for every second of underbalance, and everything downstream scales with it.", "Because the blowout preventer''s elastomers degrade rapidly if they are closed against a flowing well for long.", "Because the mud pumps cannot be stopped safely once the annulus pressure has risen above the relief valve setting."]'::jsonb, 1, 'Kick tolerance, shoe risk and kill difficulty all scale with the volume taken.'),
  ('wellcontrol', 'beginner', 'final', null, 7, 'The shut-in drill pipe pressure is what kind of quantity?', '["A pressure deficit, meaningful only alongside the mud column it sits on top of.", "An absolute formation pressure.", "A frictional loss, being the pressure needed to push mud through the bit nozzles at the moment of shut-in.", "A rate of change, showing how fast the well is pressuring up towards its balanced condition after closure."]'::jsonb, 0, 'A large reading on a shallow well and a small one on a deep well can mean the same pore pressure gradient.'),
  ('wellcontrol', 'beginner', 'final', null, 8, 'You have a stable string gauge reading and the survey. What single step gives you the pore pressure at the bit?', '["Multiply by the depth and by gravity.", "Subtract the shut-in casing pressure from it, because the difference is what the influx failed to provide at the bottom.", "Divide it by the mud density and multiply the result by the fracture gradient measured at the last casing shoe.", "Add the mud column at the true vertical depth of the bit."]'::jsonb, 3, 'One addition, and the depth used is vertical rather than along the hole.'),
  ('wellcontrol', 'beginner', 'final', null, 9, 'Why is the casing gauge normally the higher reading?', '["Because the annulus is wider.", "Its column contains the influx, which is lighter than mud and provides less pressure over its height.", "Because the choke is partly closed, and the restriction it creates shows up directly as an elevated surface reading.", "Because the annulus contains cuttings as well as mud, and the suspended solids raise the effective column density."]'::jsonb, 1, 'The bigger deficit is on the side with the light fluid in it.'),
  ('wellcontrol', 'beginner', 'final', null, 10, 'What breaks the drill pipe manometer?', '["A pump running at low rate.", "A difference between the mud weight in the pits and the mud weight already circulating in the annulus of the well.", "A float valve, a plugged bit, or the string being off bottom.", "A shut-in casing pressure that exceeds the maximum allowable annular surface pressure for the exposed hole section."]'::jsonb, 2, 'Three common cases, each with its own workaround, and the float one is the most frequent.'),
  ('wellcontrol', 'beginner', 'final', null, 11, 'The workaround for a float valve is what?', '["Pump slowly until the float opens, and read the pressure at which it does.", "Bleed the string down through the kelly cock.", "Use the shut-in casing pressure instead and subtract an allowance for the influx height in the annulus above the bit.", "Wait until gas migration raises the string pressure enough to lift the float off its seat without pumping at all."]'::jsonb, 0, 'It converts an unreadable static gauge into a readable dynamic one.'),
  ('wellcontrol', 'beginner', 'final', null, 12, 'A lateral rises hardly at all yet holds mud along its whole length. Which depth measures that?', '["True vertical depth in all cases.", "Measured depth, because fluid fills the hole along its length.", "The vertical section, since that is what determines how much fluid the wellbore can hold between two survey stations.", "Measured depth inside the string and true vertical depth in the annulus, because the annulus is where pressure acts."]'::jsonb, 1, 'A horizontal lateral holds mud along every metre of it and rises not at all.'),
  ('wellcontrol', 'beginner', 'final', null, 13, 'A hydrostatic calculation needs a height. Which one?', '["Measured depth along the hole.", "The average of the two, which accounts for the inclination of the section without needing the full survey listing.", "Measured depth multiplied by the cosine of the average inclination, which is how the survey is normally reported.", "True vertical depth, because hydrostatic pressure depends on height."]'::jsonb, 3, 'Mixing the two is the classic error, and on a horizontal well it is catastrophic.'),
  ('wellcontrol', 'beginner', 'final', null, 14, 'A liner change alters one number on the standing part. What kind of quantity is that number?', '["A volume, being what the pump actually delivers in one stroke after its efficiency is allowed for.", "A rate of flow in cubic metres per minute.", "The pressure the pump develops at the standpipe when it is run at the slow circulating rate used for a kill.", "The theoretical liner displacement, before any correction for valve leakage or for compressibility of the mud."]'::jsonb, 0, 'Multiply by strokes per minute and it becomes a rate. On its own it is a volume.'),
  ('wellcontrol', 'beginner', 'final', null, 15, 'Strokes to bit is which volume divided by pump output?', '["The annulus volume.", "The total circulating volume, which is the string and the annulus added together over the full length of the well.", "The string volume.", "The open hole annulus volume alone, since the cased section is displaced before the influx reaches the bit."]'::jsonb, 2, 'It is the surface to bit displacement and nothing else.'),
  ('wellcontrol', 'beginner', 'final', null, 16, 'To circulate bottoms up you displace which part of the well?', '["The string volume plus the annulus volume.", "The annulus volume, from the bit all the way to surface.", "The volume of the open hole section only, measured from the casing shoe down to the total depth of the well.", "The pit volume, since bottoms up is defined as one complete turnover of the active surface system."]'::jsonb, 1, 'On both wells in this course it is much larger than strokes to bit.'),
  ('wellcontrol', 'beginner', 'final', null, 17, 'Somebody quotes a stroke count for displacing the entire circulating system once. What have they quoted?', '["Twice the annulus volume in strokes.", "The number of strokes needed to circulate the influx from the bit to the choke manifold at the surface of the well.", "One round trip of the drill string, from the moment it leaves bottom to the moment it is back on bottom again.", "Strokes to bit plus bottoms up."]'::jsonb, 3, 'The kill schedule occupies only the first part of it.'),
  ('wellcontrol', 'beginner', 'final', null, 18, 'A given influx volume is tallest where in the annulus?', '["Around the drill collars, where the gap between pipe and hole is at its narrowest.", "Inside the casing above the shoe.", "At the flow line, where the returns are constricted into the smallest cross section in the circulating system.", "In the horizontal lateral, because the pipe lies against the low side and blocks part of the available area."]'::jsonb, 0, 'Which is where it enters, so it enters at its tallest and shortens as it rises.'),
  ('wellcontrol', 'beginner', 'final', null, 19, 'Kill mud is defined how?', '["Mud weighted to the fracture gradient.", "Mud that has been treated with lost circulation material so that it will not be lost to the formation during the kill.", "Mud whose hydrostatic column alone balances the formation pressure at the bit.", "The original mud, circulated at the slow rate until the influx has been removed from the annulus entirely."]'::jsonb, 2, 'It restores the primary barrier, which is what the whole operation is for.'),
  ('wellcontrol', 'beginner', 'final', null, 20, 'The kill mud density is the current density plus what?', '["The pit gain divided by the annulus capacity.", "The shut-in drill pipe pressure divided by gravity and by the true vertical depth at the bit.", "The difference between the two shut-in readings, converted into a density at the true vertical depth of the shoe.", "The ratio of the formation pressure to the fracture pressure, multiplied by the density already in the hole."]'::jsonb, 1, 'The added term is the deficit expressed as a density. One division, one addition.'),
  ('wellcontrol', 'beginner', 'final', null, 21, 'A trip margin buys what and costs what?', '["It buys rate of penetration and costs barite.", "It buys a lower shut-in casing pressure and costs a longer circulation time when the influx is eventually removed.", "It buys accuracy in the shut-in drill pipe reading and costs a small amount of pump efficiency at the kill rate.", "It buys overbalance against swab and costs kick tolerance at the shoe."]'::jsonb, 3, 'That trade is why trip margins are argued about rather than simply always applied.'),
  ('wellcontrol', 'beginner', 'final', null, 22, 'The delay between deciding to kill and having kill mud exists because of what?', '["The mud has to be weighted up in the pits, which takes barite and takes time.", "The kill sheet takes a long time to complete.", "The blowout preventer cannot be closed until the mud engineer has certified the new density in the active system.", "The pump must be run at the slow rate for a full cycle before the density in the string can be considered uniform."]'::jsonb, 0, 'That delay is the entire reason one of the two kill methods exists.'),
  ('wellcontrol', 'beginner', 'final', null, 23, 'Barite is going into the pits and the well is closed. What is going on downhole meanwhile?', '["Nothing, because the well is closed in.", "The influx dissolves into the mud, which brings the casing reading down towards the drill pipe reading over time.", "Gas migrates up the annulus, raising both surface gauges.", "The formation continues to flow until the mud weight in the pits has been raised to the calculated kill value."]'::jsonb, 2, 'Migration is why waiting is not free, and it is the argument for the Driller''s Method.'),
  ('wellcontrol', 'beginner', 'final', null, 24, 'Set the two recognised procedures side by side. What single thing separates them?', '["Whether the bottom hole pressure is held constant.", "When the kill mud is pumped relative to when the influx is circulated out.", "Which of the two shut-in gauge readings is used to build the pressure schedule that the choke operator follows.", "Whether the well is circulated up the annulus or reverse circulated down it and back up through the drill string."]'::jsonb, 1, 'Both hold the bottom hole pressure constant. Only the order of two operations differs.'),
  ('wellcontrol', 'beginner', 'final', null, 25, 'The Driller''s Method requires how many circulations?', '["One, the same as Wait and Weight.", "Three, because the kill mud must be circulated round twice to be certain that the original mud has been fully displaced.", "As many as it takes for the shut-in casing pressure to fall to zero with the pumps stopped and the choke closed.", "Two: one to remove the influx, one to replace the mud."]'::jsonb, 3, 'The first circulation uses whatever mud is already in the hole.'),
  ('wellcontrol', 'beginner', 'final', null, 26, 'Wait and Weight gives a lower pressure where?', '["At the casing shoe, because kill mud reaches the bit while the influx is still low in the annulus.", "At the surface choke manifold.", "At the bit, since the heavier mud in the string reduces the pressure required to hold the formation back at depth.", "At the pump, because a single circulation means the pump runs for less total time at the kill rate."]'::jsonb, 0, 'Heavier mud below the shoe earlier means less surface pressure is needed, and the shoe feels the difference.'),
  ('wellcontrol', 'beginner', 'final', null, 27, 'The Driller''s Method is defended on what ground?', '["It uses substantially less barite overall.", "It produces a lower maximum casing pressure, which is the binding constraint on almost every well that takes a kick.", "It starts immediately, and getting a migrating influx out early is worth a lot.", "It requires no slow circulating rate pressure, because the first circulation is run at the drilling rate throughout."]'::jsonb, 2, 'It is a trade between shoe risk and delay risk, and the well conditions decide it.'),
  ('wellcontrol', 'beginner', 'final', null, 28, 'What actually controls the bottom hole pressure during a kill?', '["The pump, held at a fixed rate.", "The choke, adjusted so the drill pipe pressure follows the schedule.", "The kill mud, which balances the formation as soon as it has been circulated all the way round the system.", "The blowout preventer, which holds a constant annular pressure regardless of what the choke operator is doing."]'::jsonb, 1, 'The pump rate is held steady so that the friction term stays steady. The choke does the controlling.'),
  ('wellcontrol', 'beginner', 'final', null, 29, 'Nothing on the sheet is computed from mud rheology. Where does its friction term come from instead?', '["By measuring it at a low pump rate before it is needed, and repeating the measurement routinely.", "By computing it from the mud rheology.", "By reading the standpipe pressure at the moment the well is shut in and subtracting the shut-in drill pipe pressure.", "By interpolating between the initial and final circulating pressures that the kill sheet calculation produces."]'::jsonb, 0, 'It is measured, which is why the kill sheet needs no hydraulics model at all.'),
  ('wellcontrol', 'beginner', 'final', null, 30, 'A supervisor picks a low rate for the kill. Give the two reasons behind that choice.', '["To avoid overheating the pump liners.", "Because a slow rate allows the influx to expand gradually, which keeps the pit gain within the trip tank capacity.", "Because the kill mud and the original mud would mix at the interface if they were pumped at a higher velocity.", "Less annulus friction at the shoe, and time for the choke operator to react."]'::jsonb, 3, 'Two reasons, and the shoe one is usually the harder constraint of the two.'),
  ('wellcontrol', 'beginner', 'final', null, 31, 'Suppose the operator succeeds in keeping the bottom steady all the way through. What has that accomplished?', '["A constant reading on the casing gauge.", "A uniform expansion rate for the influx as it rises, which is what allows the schedule to be drawn as a straight line.", "No further influx, and no fracture at the shoe.", "A steady drill pipe pressure throughout both circulations of the Driller''s Method and the single Wait and Weight pass."]'::jsonb, 2, 'Slightly above the pore pressure and below the fracture pressure everywhere at once.'),
  ('wellcontrol', 'beginner', 'final', null, 32, 'Of the two procedures, which one cannot begin until the arithmetic is finished?', '["Both, equally and for the same reason.", "Wait and Weight, whose schedule describes a falling drill pipe pressure.", "The Driller''s Method, because its first circulation must be run at exactly the pressure recorded at the moment of shut-in.", "Neither, because both are controlled by holding the casing pressure steady and using the drill pipe only as a check."]'::jsonb, 1, 'The Driller''s first circulation holds a constant drill pipe pressure and needs very little arithmetic.'),
  ('wellcontrol', 'beginner', 'final', null, 33, 'Take the first pass of the two-circulation procedure. How does the string gauge behave through it?', '["Stays constant, because the mud density in the string is not changing.", "Falls steadily to the final circulating value.", "Rises as the influx nears surface and expands, then drops sharply once it has been bled through the choke.", "Follows exactly the same schedule as a Wait and Weight kill, since both hold the bottom hole pressure constant."]'::jsonb, 0, 'Constant string density means constant hydrostatic, so a constant surface pressure holds the bottom steady.'),
  ('wellcontrol', 'beginner', 'final', null, 34, 'You are about to attempt this tier. Which geometry will you be walking?', '["The horizontal well from the lessons.", "Both, with three fields drawn from each so that two separate span walks have to be completed by the learner.", "The slant well, though the lessons taught the same quantities on the horizontal one.", "Whichever of the two the learner selects in the panel before beginning the capstone attempt for the tier."]'::jsonb, 2, 'Same method, different well, and that is deliberate.'),
  ('wellcontrol', 'beginner', 'final', null, 35, 'What kinds of quantity are graded in this tier?', '["Kill mud weight and formation pressure.", "Volumes, stroke counts and true vertical depths.", "The initial and final circulating pressures, together with the schedule of pressures that connects the two of them.", "The influx height, its density and its classification as gas, liquid or a mixture of the two together."]'::jsonb, 1, 'Pressures belong to the next tier. This one certifies the span walk.'),
  ('wellcontrol', 'beginner', 'final', null, 36, 'Two of the six graded values are vertical depths. What justifies including them here?', '["Because they are the simplest fields to mark.", "Because the volumes cannot be computed at all until the vertical rise of every section has been established first.", "Because they are the only two quantities in the tier that cannot be checked against the published golden files.", "Because the next tier''s pressure work needs them and the same survey walk produces them."]'::jsonb, 3, 'They are the bridge from the geometry work into the pressure work.'),
  ('wellcontrol', 'beginner', 'final', null, 37, 'Why are the stroke tolerances looser than the volume tolerances?', '["Strokes carry a measured pump efficiency, so a small legitimate spread exists.", "Because stroke counts are larger numbers.", "Because the volumes are graded against the published goldens whereas the strokes are graded against the panel output.", "Because pump output per stroke is not supplied and each learner has to estimate it from the liner dimensions."]'::jsonb, 0, 'Volumes are pure geometry and should agree to many figures. Strokes inherit an efficiency.'),
  ('wellcontrol', 'beginner', 'final', null, 38, 'List what a learner leaves this tier holding, ready for the kill sheet work.', '["The completed kill sheet with all four outputs.", "The classification of the influx together with the height that it occupies in the annulus at the moment of shut-in.", "The standing part of a kill sheet: volumes, strokes and the two depths.", "The maximum allowable annular surface pressure, computed from the leak-off test at the last casing shoe."]'::jsonb, 2, 'Six inputs are in hand. The kick event supplies the remaining three.'),
  ('wellcontrol', 'beginner', 'final', null, 39, 'Which three inputs can only come from the kick event itself?', '["The mud weight, the bit depth and the pump rate.", "The two shut-in gauge readings and the pit gain.", "The pump efficiency, the annulus capacity at the collars and the slow circulating rate pressure at the kill rate.", "The fracture gradient at the shoe, the pore pressure in the zone and the bottom hole temperature at total depth."]'::jsonb, 1, 'That is why a kill sheet can be prepared in advance but never completed in advance.'),
  ('wellcontrol', 'beginner', 'final', null, 40, 'The standing part of a kill sheet goes stale because of what?', '["The paper degrades in the doghouse.", "The mud weight is raised at every casing point, and every entry on the sheet depends on the density of the fluid.", "The pump liners are changed on a regular schedule, which alters the output per stroke used throughout the sheet.", "The hole gets deeper, so the volumes and stroke counts change continuously."]'::jsonb, 3, 'It changes every stand, which is why keeping it current is a routine duty rather than a calculation.'),
  ('wellcontrol', 'beginner', 'final', null, 41, 'Where is the stack taken to be, and what lies between it and the gauges?', '["That it is at surface, with no riser and no choke line between it and the gauges.", "That it is a subsea stack on a floater.", "That it is rated well above any pressure the well can develop, so its rating never appears in the arithmetic.", "That it is kept closed for the whole operation, including the period while the kill mud is being circulated round."]'::jsonb, 0, 'The Expert tier states the assumption formally and supplies the offshore correction.'),
  ('wellcontrol', 'beginner', 'final', null, 42, 'The one sentence of the Associate tier is what?', '["Always shut the well in immediately.", "Build the kill mud, circulate it round at the measured slow rate, and confirm the well is static before opening up.", "Keep the bottom hole pressure above the pore pressure, and know what it is doing when you cannot.", "Read both gauges, record the pit gain, and pass the three numbers to whoever is completing the kill sheet."]'::jsonb, 2, 'Everything in the five modules is either a way of keeping it there or a way of finding out where it is.');
